#!/usr/bin/env python3
"""Check explicit app-storage reservation and honest OS-write error handling."""
from pathlib import Path
from host_toolchain import java_home, launcher_classpath
import json,tempfile,subprocess
ROOT=Path(__file__).resolve().parents[1];jdk=java_home()
cp=launcher_classpath()
param=json.loads((ROOT/'client/startup/param.json').read_text());assert param['downloadDataSize']==256 and param['titleId']=='PPSA99874'
source=r'''
import java.nio.file.*;import java.io.*;import java.lang.reflect.*;
public class StorageCheck {
 public static void main(String[]args)throws Exception {
  var friendly=ProsperoLauncher.class.getDeclaredMethod("friendly",Exception.class);friendly.setAccessible(true);
  String[] reasons={"No space left on device","Disk quota exceeded","Permission denied","Read-only filesystem","Unclassified"};String[] codes={"ENOSPC","QUOTA","ACCESS","READ_ONLY","IO"};
  for(int i=0;i<reasons.length;i++){var error=new FileSystemException("/download0/ProsperoCraft/cache/public-file",null,reasons[i]);if(!ProsperoStorage.code(error).equals(codes[i]))throw new AssertionError("wrong category");String message=(String)friendly.invoke(null,error);if(i<2&&(!message.contains("App storage")||!message.contains("loader metadata")||message.contains("4GiB")))throw new AssertionError("misleading full-console error");}
  var generic=new IOException("No space left on device");if(!ProsperoStorage.code(generic).equals("ENOSPC"))throw new AssertionError();
  Path folder=Path.of(args[0]);var library=new ProsperoLibrary(folder);var instance=library.add("Keep this world","26.3",1);Files.writeString(library.game(instance).resolve("world-bytes"),"KEEP");
  var model=new ProsperoLauncher(new ProsperoAuth(),folder,null);if(!model.tick(0)[13].equals("2")||!model.tick(0)[32].equals("Keep this world")||!Files.readString(library.game(instance).resolve("world-bytes")).equals("KEEP"))throw new AssertionError("library/world mutated");
  if(!model.tick(0)[67].contains(folder.toString()))throw new AssertionError("actual path hidden");
  // Shared storage is proven through real Java operations before copy/switch.
  Path migration=folder.resolve("migration"),legacy=migration.resolve("download/ProsperoCraft"),shared=migration.resolve("data/ProsperoCraft");Files.createDirectories(shared.getParent());
  var original=new ProsperoLibrary(legacy);var kept=original.add("Migration world","26.3",3);Files.writeString(original.game(kept).resolve("world.txt"),"ORIGINAL WORLD");var account=new ProsperoAccountStore(legacy);account.save("fixture-refresh");String libraryBytes=Files.readString(legacy.resolve("library.json"));
  var failed=ProsperoStorageRoot.select(legacy,shared,ProsperoStorageRoot::probe,(from,to)->{Files.writeString(to,"partial");throw new IOException("No space left on device");});
  if(!failed.root().equals(legacy)||Files.exists(shared)||!Files.readString(legacy.resolve("library.json")).equals(libraryBytes)||!Files.readString(original.game(kept).resolve("world.txt")).equals("ORIGINAL WORLD"))throw new AssertionError("failed migration changed active data");
  var chosen=ProsperoStorageRoot.select(legacy,shared,ProsperoStorageRoot::probe,ProsperoStorageRoot::copy);if(!chosen.root().equals(shared))throw new AssertionError("did not switch after verified resume");
  var migrated=new ProsperoLibrary(shared);if(!migrated.instances().get(0).id.equals(kept.id)||!Files.readString(migrated.game(migrated.instances().get(0)).resolve("world.txt")).equals("ORIGINAL WORLD")||!new ProsperoAccountStore(shared).load().equals("fixture-refresh")||!Files.readString(legacy.resolve("library.json")).equals(libraryBytes)||!account.load().equals("fixture-refresh"))throw new AssertionError("migration lost instance/account/original");
  if(!ProsperoStorageRoot.select(legacy,shared,ProsperoStorageRoot::probe,ProsperoStorageRoot::copy).root().equals(shared))throw new AssertionError("shared root not sticky");
  try{ProsperoStorageRoot.select(legacy,shared,p->{throw new AccessDeniedException("fixture");},ProsperoStorageRoot::copy);throw new AssertionError("silently opened stale legacy worlds");}catch(IOException expected){}
  Files.writeString(legacy.resolve(ProsperoStorageRoot.POINTER),"partial");try{ProsperoStorageRoot.select(legacy,shared,p->{throw new AccessDeniedException("fixture");},ProsperoStorageRoot::copy);throw new AssertionError("invalid marker reopened stale data");}catch(IOException expected){}Files.writeString(legacy.resolve(ProsperoStorageRoot.POINTER),"shared-v1\n");
  Files.move(shared,shared.resolveSibling("offline-data"));try{ProsperoStorageRoot.select(legacy,shared,ProsperoStorageRoot::probe,ProsperoStorageRoot::copy);throw new AssertionError("recreated missing shared data");}catch(IOException expected){}
  Path fresh=folder.resolve("fresh"),freshShared=fresh.resolve("data/ProsperoCraft"),freshLegacy=fresh.resolve("download/ProsperoCraft");Files.createDirectories(freshShared.getParent());if(!ProsperoStorageRoot.select(freshLegacy,freshShared,ProsperoStorageRoot::probe,ProsperoStorageRoot::copy).root().equals(freshShared)||Files.exists(freshLegacy.resolve("library.json")))throw new AssertionError("fresh install used fixed container for bulk");
  Path blocked=folder.resolve("blocked");try{ProsperoStorageRoot.select(blocked.resolve("old"),blocked.resolve("new"),p->{throw new AccessDeniedException("fixture");},ProsperoStorageRoot::copy);throw new AssertionError();}catch(IOException expected){}if(Files.exists(blocked))throw new AssertionError("created alternate empty library on access refusal");
  Path linkCase=folder.resolve("link-case"),linkLegacy=linkCase.resolve("download/ProsperoCraft"),linkShared=linkCase.resolve("data/ProsperoCraft");Files.createDirectories(linkShared.getParent());new ProsperoLibrary(linkLegacy);Path outside=linkCase.resolve("outside");Files.writeString(outside,"UNCHANGED");Files.createSymbolicLink(linkLegacy.resolve("unexpected"),outside);if(!ProsperoStorageRoot.select(linkLegacy,linkShared,ProsperoStorageRoot::probe,ProsperoStorageRoot::copy).root().equals(linkLegacy)||!Files.readString(outside).equals("UNCHANGED"))throw new AssertionError("followed migration link");
  Path mutation=folder.resolve("mutation"),mutationOld=mutation.resolve("download/ProsperoCraft"),mutationNew=mutation.resolve("data/ProsperoCraft");Files.createDirectories(mutationNew.getParent());new ProsperoLibrary(mutationOld);Files.writeString(mutationOld.resolve("change.txt"),"BEFORE");var changed=ProsperoStorageRoot.select(mutationOld,mutationNew,ProsperoStorageRoot::probe,(from,to)->{ProsperoStorageRoot.copy(from,to);if(from.getFileName().toString().equals("change.txt"))Files.writeString(from,"AFTER CHANGE");});if(!changed.root().equals(mutationOld)||Files.exists(mutationNew))throw new AssertionError("committed changing source");
  Path foreign=folder.resolve("foreign"),foreignOld=foreign.resolve("download/ProsperoCraft"),foreignNew=foreign.resolve("data/ProsperoCraft");Files.createDirectories(foreignNew.getParent());new ProsperoLibrary(foreignOld);Path foreignStage=foreignNew.resolveSibling(".ProsperoCraft-migration");Files.createDirectory(foreignStage);Files.writeString(foreignStage.resolve("unowned"),"KEEP");if(!ProsperoStorageRoot.select(foreignOld,foreignNew,ProsperoStorageRoot::probe,ProsperoStorageRoot::copy).root().equals(foreignOld)||!Files.readString(foreignStage.resolve("unowned")).equals("KEEP"))throw new AssertionError("modified foreign staging tree");
  Path conflict=folder.resolve("conflict"),conflictOld=conflict.resolve("download/ProsperoCraft"),conflictNew=conflict.resolve("data/ProsperoCraft");new ProsperoLibrary(conflictOld).add("Old world","26.3",1);new ProsperoLibrary(conflictNew).add("Separate world","26.3",1);try{ProsperoStorageRoot.select(conflictOld,conflictNew,ProsperoStorageRoot::probe,ProsperoStorageRoot::copy);throw new AssertionError("silently chose between conflicting libraries");}catch(IOException expected){}if(!new ProsperoLibrary(conflictOld).instances().get(0).name.equals("Old world")||!new ProsperoLibrary(conflictNew).instances().get(0).name.equals("Separate world"))throw new AssertionError("conflicting library was modified");
  // Simulate failure after READY but before the directory rename, then retry.
  Path commitCase=folder.resolve("commit-case"),commitOld=commitCase.resolve("download/ProsperoCraft"),commitNew=commitCase.resolve("data/ProsperoCraft");Files.createDirectories(commitNew.getParent());new ProsperoLibrary(commitOld);var count=new java.util.concurrent.atomic.AtomicInteger();var notCommitted=ProsperoStorageRoot.select(commitOld,commitNew,ProsperoStorageRoot::probe,(from,to)->{ProsperoStorageRoot.copy(from,to);if(count.incrementAndGet()==1){Files.createDirectory(commitNew);Files.writeString(commitNew.resolve("race"),"KEEP");}});if(!notCommitted.root().equals(commitOld)||!Files.readString(commitNew.resolve("race")).equals("KEEP"))throw new AssertionError("commit raced overwrite");Files.delete(commitNew.resolve("race"));if(!ProsperoStorageRoot.select(commitOld,commitNew,ProsperoStorageRoot::probe,ProsperoStorageRoot::copy).root().equals(commitNew))throw new AssertionError("verified commit retry failed");
  System.setProperty("ps5.launcher.root",folder.resolve("explicit").toString());try{if(!ProsperoStorageRoot.current().root().equals(folder.resolve("explicit")))throw new AssertionError("explicit root ignored");}finally{System.clearProperty("ps5.launcher.root");}

  System.out.println("PASS shared-root proof/fallback/fail-closed/copy-resume/account+world verification/symlink+source-change refusal;256MiBmanifest/same title, typed ENOSPC/quota/access/read-only categories and app-local full message, unchanged library/world path and visible data root; no invented free-space or console resize claim");
 }
}
'''
with tempfile.TemporaryDirectory(prefix='prospero-storage-')as folder:
 w=Path(folder).resolve();(w/'StorageCheck.java').write_text(source)
 subprocess.run([str(jdk/'bin/javac'),'--release','25','-cp',cp,'-d',str(w),*[str(p)for p in (ROOT/'client/launcher/java').glob('*.java')],str(w/'StorageCheck.java')],check=True)
 subprocess.run([str(jdk/'bin/java'),'-cp',str(w)+':'+cp,'StorageCheck',str(w/'test')],check=True,timeout=30)
